def find_double_writers(ownership, writers):
    bad = []
    for field, owner in ownership.items():
        if set(writers.get(field, [])) != {owner}:
            bad.append(field)
    return sorted(bad)

def find_drift(ownership, snapshots):
    out = []
    for field, owner in ownership.items():
        owner_value = snapshots.get(owner, {}).get(field)
        for system, snap in snapshots.items():
            if system == owner or field not in snap:
                continue
            if snap[field] != owner_value:
                out.append((field, system, snap[field], owner_value))
    return sorted(out)

dw = find_double_writers(OWNERSHIP, WRITERS)
