CHAIN = ["requested", "approved", "provisioned", "synced", "audited", "revoked"]

EVENTS = {
    "emp-anna":  [("requested", True), ("approved", True), ("provisioned", True),
                  ("synced", True), ("audited", True)],
    "ctr-1188":  [("requested", True), ("approved", True), ("provisioned", True),
                  ("synced", True)],
    "emp-raj":   [("requested", True), ("provisioned", True),
                  ("synced", False)],
    "ctr-2044":  [("requested", True), ("approved", True), ("provisioned", True),
                  ("synced", True), ("audited", True), ("revoked", True)],
}
TERMINATED = {"ctr-1188", "ctr-2044"}

def audit_lifecycle(events, user):
    findings = []
    taken = set()
    for transition, evidence in events:
        idx = CHAIN.index(transition)
        for predecessor in CHAIN[:idx]:
            if predecessor not in taken and f"skipped transition: {predecessor}" not in findings:
                findings.append(f"skipped transition: {predecessor}")
        if not evidence:
            findings.append(f"missing evidence: {transition}")
        taken.add(transition)
    if user in TERMINATED and "revoked" not in taken:
        findings.append("never revoked")
    return findings

total = 0
for user in ["emp-anna", "ctr-1188", "emp-raj", "ctr-2044"]:
    findings = audit_lifecycle(EVENTS[user], user)
    total += len(findings)
    status = "CLEAN" if not findings else "; ".join(findings)
    print(f"{user}: {status}")
print(f"total findings: {total}")

