def diff_state(expected, actual):
    out = []
    for key, act in actual.items():
        app, user = key
        if key not in expected:
            if act:
                out.append(f"{app}/{user}: expected unprovisioned, is active")
            continue
        exp = expected[key]
        if exp != act:
            out.append(f"{app}/{user}: expected {'active' if exp else 'inactive'}, is {'active' if act else 'inactive'}")
    return sorted(out)

expected = replay_events(EVENTS)
