ROLES = {
    "support":  {"perms": ["read:tickets", "write:tickets"], "inherits": ["ops-l2"]},
    "ops-l2":   {"perms": ["read:runbooks", "read:billing"], "inherits": ["ops-l1"]},
    "ops-l1":   {"perms": ["read:dashboards"],               "inherits": []},
    "finance":  {"perms": ["read:billing", "export:billing"],"inherits": []},
}

JUSTIFIED = {
    "support":  {"read:tickets", "write:tickets", "read:dashboards"},
    "ops-l2":   {"read:runbooks", "read:dashboards"},
    "ops-l1":   {"read:dashboards"},
    "finance":  {"read:billing", "export:billing"},
}

def effective_permissions(roles, role):
    perms = set()
    stack = [role]
    seen = set()
    while stack:
        r = stack.pop()
        if r in seen:
            continue
        seen.add(r)
        perms.update(roles[r]["perms"])
        stack.extend(roles[r]["inherits"])
    return sorted(perms)

def find_unjustified(roles, justified):
    out = []
    for role in roles:
        for perm in effective_permissions(roles, role):
            if perm not in justified.get(role, set()):
                out.append(f"{role}: {perm}")
    return sorted(out)

for role in sorted(ROLES):
    print(f"{role}: {', '.join(effective_permissions(ROLES, role))}")
findings = find_unjustified(ROLES, JUSTIFIED)
for x in findings:
    print(f"UNJUSTIFIED {x}")
print(f"unjustified grants: {len(findings)}")

