def compute_diff(before, after):
    changes = []
    for role in sorted(set(before) | set(after)):
        b = before.get(role, set())
        a = after.get(role, set())
        for perm in sorted(a - b):
            changes.append(f"{role}: +{perm}")
        for perm in sorted(b - a):
            changes.append(f"{role}: -{perm}")
    return sorted(changes)

def check_drift(actual_diff, intended_diff):
    actual_set = set(actual_diff)
    intended_set = set(intended_diff)
    unintended = sorted(actual_set - intended_set)
    missing = sorted(intended_set - actual_set)
    return unintended, missing

actual = compute_diff(BEFORE, AFTER)
unintended, missing = check_drift(actual, INTENDED)
for c in actual:
    print(f"actual: {c}")
for c in unintended:
    print(f"DRIFT: {c}")
