SOURCE_OF_TRUTH = {"voss": False, "okafor": True, "lin": True}

DELIVERIES = [
    ("crm",       "voss", False, 200),
    ("billing",   "voss", False, 200),
    ("analytics", "voss", False, 401),
    ("crm",       "lin",  True,  200),
]

APP_STATE = {
    ("crm", "voss"): True,
    ("billing", "voss"): True,
    ("analytics", "voss"): True,
    ("crm", "okafor"): True,
    ("crm", "lin"): False,
    ("analytics", "okafor"): False,
}

def apply_webhooks(deliveries, app_state):
    dead_letter = []
    for app, user, new_active, status in deliveries:
        if 200 <= status < 300:
            app_state[(app, user)] = new_active
        else:
            dead_letter.append(f"{app}/{user}: HTTP {status}")
    return dead_letter

def reconcile(source, app_state):
    repairs = []
    for (app, user), active in sorted(app_state.items()):
        want = source[user]
        if active != want:
            app_state[(app, user)] = want
            repairs.append(f"{app}/{user}: {'activated' if want else 'deactivated'} by sweep")
    return sorted(repairs)

dead = apply_webhooks(DELIVERIES, APP_STATE)
for d in dead:
    print(f"dead-letter: {d}")
