def resolve_conflicts(contract, values):
    repairs = []
    violations = []
    for field, owner in contract.items():
        if owner.startswith("local:"):
            home = owner.split(":", 1)[1]
            for system, held in values.items():
                if system != home and field in held:
                    violations.append(f"{system}.{field}: holds local-only field of {home}")
            continue
        want = values.get(owner, {}).get(field)
        for system, held in values.items():
            if system == owner or field not in held:
                continue
            if held[field] != want:
                repairs.append(f"{system}.{field}: '{held[field]}' -> '{want}'")
    return sorted(repairs), sorted(violations)

repairs, violations = resolve_conflicts(CONTRACT, VALUES)
for r in repairs:
    print(f"repair: {r}")
for v in violations:
    print(f"VIOLATION: {v}")
