FIXTURES = {
    "sso_login_after_disable": False,
    "scim_events": {"crm": "200", "billing": "200", "analytics": None},
    "drift_rows": 3,
    "audit_sample": [{"gid": "g1", "approval": True}, {"gid": "g2", "approval": False},
                     {"gid": "g3", "approval": True}, {"gid": "g4", "approval": False},
                     {"gid": "g5", "approval": True}],
}

def hook_sso(f):
    ok = not f["sso_login_after_disable"]
    return ok, "no assertion issued" if ok else "LOGIN SUCCEEDED after disable"

def hook_scim(f):
    missing = sorted(app for app, ev in f["scim_events"].items() if ev is None)
    if missing:
        return False, f"no event: {', '.join(missing)}"
    return True, "all apps received deactivate"

def hook_rbac(f):
    ok = f["drift_rows"] == 0
    return ok, f"{f['drift_rows']} drift rows"

def hook_audit(f):
    total = len(f["audit_sample"])
    missing = sum(1 for g in f["audit_sample"] if not g["approval"])
    return missing == 0, f"{missing}/{total} sampled grants missing approval"

def run_review(fixtures):
    hooks = [("sso", hook_sso), ("scim-replay", hook_scim),
             ("rbac-diff", hook_rbac), ("audit-sample", hook_audit)]
    failed = 0
    for name, fn in hooks:
        ok, evidence = fn(fixtures)
        failed += (not ok)
        print(f"{name}: {'PASS' if ok else 'FAIL'} — {evidence}")
    if failed == 0:
        print("claim VERIFIED")
    else:
        print(f"claim UNVERIFIED — {failed} hook(s) failed")

run_review(FIXTURES)

