REQUIRED = ["constraint", "selected", "rejected", "named_failure",
            "verification", "invalidation"]

PACKETS = {
    "friday-big-bang": {"constraint": "no window >1h", "selected": "big-bang cutover",
                        "rejected": "", "named_failure": "",
                        "verification": "SSO login works", "invalidation": ""},
    "staged-rings":    {"constraint": "no window >1h", "selected": "staged cutover",
                        "rejected": "big-bang", "named_failure": "mapping bug x4000 over a weekend",
                        "verification": "hourly recon diff per ring", "invalidation": "drift invisible to diff"},
    "staged-rings-daily-diff": {"constraint": "no window >1h", "selected": "staged cutover, nightly recon",
                        "rejected": "big-bang", "named_failure": "mapping bug inside a 150-user ring",
                        "verification": "daily recon diff per ring", "invalidation": "drift invisible to diff"},
}

DETECT_HOURS = {"quarterly-review": 1080, "daily-recon-diff": 24, "hourly-recon-diff": 1}

PLANS = {
    "friday-big-bang": {"rollout": "big-bang", "ring_size": 0, "population": 4000,
                        "detection": "quarterly-review"},
    "staged-rings":    {"rollout": "staged", "ring_size": 50, "population": 4000,
                        "detection": "hourly-recon-diff"},
    "staged-rings-daily-diff": {"rollout": "staged", "ring_size": 150, "population": 4000,
                        "detection": "daily-recon-diff"},
}

def review_packet(packet):
    missing = []
    for key in REQUIRED:
        if not packet.get(key):
            missing.append(key)
    return sorted(missing)

def simulate_failure(plan, affected_frac, detect_hours_by_mechanism):
    exposure = plan["ring_size"] if plan["rollout"] == "staged" else plan["population"]
    blast = round(exposure * affected_frac)
    detect = detect_hours_by_mechanism[plan["detection"]]
    return blast, detect

# ── fixed harness (do not edit) ──────────────────────────────────────────
for name in ["friday-big-bang", "staged-rings", "staged-rings-daily-diff"]:
    missing = review_packet(PACKETS[name])
    if missing:
        print(f"{name}: packet INCOMPLETE — missing {', '.join(missing)}")
    else:
        print(f"{name}: packet complete")
    blast, detect = simulate_failure(PLANS[name], 0.0295, DETECT_HOURS)
    blast_ok, detect_ok = blast <= 5, detect <= 1
    ok = blast_ok and detect_ok
    failed = [t for t, good in (("blast", blast_ok), ("detection", detect_ok)) if not good]
    if ok:
        why = ""
    elif len(failed) == 1:
        why = f" — fails the {failed[0]} tooth"
    else:
        why = " — fails both teeth (blast + detection)"
    print(f"{name}: blast={blast} users, detection={detect}h -> {'PASS' if ok else 'FAIL'} vs constraint{why}")
